// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address proposedNewOwner) public {
        vm.assume(proposedNewOwner != address(0));

        address beforeOwner = c.owner();

        vm.prank(caller);
        bool ok;
        try c.setOwner(proposedNewOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == beforeOwner);
    }
}
